    {
      "after_item": "S6_PERSONAL",
      "title_raw": "가. 인체를 보호하기 위해 필요한 조치사항 및 보호구",
      "reason": "코드없음",
      "statements": [
        {
          "key": "조치",
          "value": "가능하다면 누출용기를 돌려 액체보다는 가스로 방출되도록 하시오."
        ,
        "line": "L1"
        },
        {
          "key": "조치",
          "value": "가스가 완전히 확산되어 희석될 때까지 오염지역을 격리하시오."
        ,
        "line": "L2"
        },
        {
          "key": "조치",
          "value": "유출물을 만지거나 유출된 곳을 걸어 다니지 마시오."
        ,
        "line": "L3"
        },
        {
          "key": "조치",
          "value": "누출성 가스 화재 시 누출을 안전하게 막을 수 없다면 불을 끄려하지 마시오."
        ,
        "line": "L4"
        },
        {
          "key": "조치",
          "value": "누출원에 직접 주수하지 마시오."
        ,
        "line": "L5"
        },
        {
          "key": "조치",
          "value": "매우 미세한 입자는 화재나 폭발을 일으킬 수 있으므로 모든 점화원을 제거하시오."
        ,
        "line": "L6"
        },
        {
          "key": "조치",
          "value": "물 분무를 이용하여 증기를 줄이거나 증기구름을 흩어트리고 물이 누출물과 접촉되지 않도록 하시오."
        ,
        "line": "L7"
        },
        {
          "key": "조치",
          "value": "물질 취급 시 모든 장비를 반드시 접지하시오."
        ,
        "line": "L9"
        },
        {
          "key": "조치",
          "value": "위험하지 않다면 누출을 멈추시오."
        ,
        "line": "L10"
        },
        {
          "key": "조치",
          "value": "피해야 할 물질 및 조건에 유의하시오."
        ,
        "line": "L11"
        }
      ]
    ,
      "suggested_code": "S6_PERSONAL"
    ,
      "line": "L33"
    },
    {
      "after_item": "S6_ENV",
      "title_raw": "나. 환경을 보호하기 위해 필요한 조치사항",
      "reason": "코드없음",
      "statements": [
        {
          "key": "조치",
          "value": "증기가 하수구, 환기장치, 밀폐공간을 통해 확산되지 않도록 하시오."
        ,
        "line": "L13"
        }
      ]
    ,
      "suggested_code": "S6_ENV"
    ,
      "line": "L12"
    },
    {
      "after_item": "S6_CLEANUP",
      "title_raw": "다. 정화 또는 제거 방법",
      "reason": "코드없음",
      "statements": [
        {
          "key": "조치",
          "value": "가스가 완전히 기화되어 제거될 때까지 기다리시오. 단, 주변에 가연성 물질 등 점화원이 있는 경우에는 모든 점화원을 제거하시오."
        ,
        "line": "L15"
        }
      ]
    ,
      "suggested_code": "S6_CLEANUP"
    ,
      "line": "L14"
    }
  ]
}

